-- Node: brugada-ecg-patterns (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"info","module":2,"title":"ECG Pattern Types","body":"**Brugada ECG Patterns:**\n\n**Type 1 (Coved) — DIAGNOSTIC**\n• Coved ST elevation ≥2mm in ≥1 lead (V1-V3)\n• Followed by T-wave inversion\n• Concave or straight ST descent below baseline\n• **This is the ONLY diagnostic pattern**\n\n**Type 2 (Saddleback) — SUGGESTIVE ONLY**\n• Saddleback ST elevation ≥0.5mm\n• J-point elevation ≥1mm\n• Positive or biphasic T wave\n• Requires provocation test if clinical suspicion\n\n**Type 3 — No longer considered diagnostic**\n• Now considered normal variant\n\n**Tip: Use HIGH precordial leads**\n• Place V1/V2 in 2nd or 3rd intercostal space\n• Increases sensitivity for detecting patterns","citation":[2,3],"next":"brugada-phenocopy-check","images":[{"src":"images/brugada/brugada-type1-ecgpedia.png","alt":"12-lead ECG showing Brugada Type 1 coved ST elevation pattern","caption":"Brugada Type 1 pattern: coved ST elevation in right precordial leads. CardioNetworks ECGpedia / P.G. Postema, CC BY-SA 3.0, Wikimedia Commons."},{"src":"images/brugada/brugada-type2-ecgpedia.png","alt":"12-lead ECG showing Brugada Type 2 saddleback ST elevation pattern","caption":"Brugada Type 2 saddleback pattern: suggestive, not diagnostic without conversion to Type 1. CardioNetworks ECGpedia, CC BY-SA 3.0, Wikimedia Commons."},{"src":"images/brugada/brugada-ecg-patterns.jpg","alt":"Brugada syndrome ECG pattern in precordial leads V1 V2 and V3","caption":"Typical Type 1 Brugada pattern in V1-V3. PeaBrainC, CC BY-SA 4.0, Wikimedia Commons."}],"calculatorLinks":[{"id":"brugada-shanghai","label":"Shanghai Score"}],"summary":"Only Type 1 coved diagnostic — high precordial leads increase sensitivity","skippable":true}'::jsonb
WHERE id = 'brugada-ecg-patterns' AND tree_id = 'brugada-syndrome';

