UPDATE decision_nodes SET data = '{"type":"question","module":2,"title":"Reperfusion Strategy","body":"**Anticoagulation** — start immediately:\n• [UFH](#/drug/ufh/pe) — no bolus if thrombolysis imminent; low-dose infusion ≤500 U/hr\n• UFH preferred (can be stopped if hemorrhage)\n\n**Systemic thrombolysis** — only intervention with mortality benefit data.\n\n**Dosing options:**\n• Standard: [Alteplase](#/drug/alteplase/pulmonary) **100 mg IV over 2h** (10–20 mg bolus, remainder over 2h)\n• Reduced-dose: **50 mg IV** over 2h (emerging — less bleeding, equivalent efficacy; HI-PEITHO 2026)\n• Cardiac arrest: **50 mg IV bolus** + sustained CPR\n• **Tenecteplase (alternative, off-label):** weight-based single bolus — 30 mg (<60 kg), 35 mg (60–69), 40 mg (70–79), 45 mg (80–89), 50 mg (≥90 kg). Single bolus advantage; mortality similar to alteplase.\n\n**2026 update:** Mechanical thrombectomy now preferred over CDT for stable-enough patients (PEERLESS-I trial). STRATIFY (2026) shows peripheral 20 mg tPA over 6h equivalent to CDT.","citation":[1,6,7,8],"options":[{"label":"Systemic Thrombolysis","description":"No absolute contraindications — proceed with alteplase","next":"pe-anticoag-selection"},{"label":"Thrombolysis Contraindicated","description":"Recent surgery, active bleeding, prior ICH, etc.","next":"pe-advanced-interventions","urgency":"urgent"},{"label":"Refractory Shock / Arrest","description":"Failed thrombolysis or deteriorating despite treatment","next":"pe-advanced-interventions","urgency":"critical"}],"treatment":{"firstLine":{"drug":"Alteplase","dose":"100 mg (or 50 mg reduced-dose; 0.6 mg/kg max 50 mg in arrest)","route":"IV","frequency":"Over 2 hours (10–20 mg bolus, remainder over 2h); bolus if cardiac arrest","duration":"Single dose","notes":"Cardiac arrest: 50 mg IV bolus + CPR; avoid concurrent heparin bolus. Tenecteplase alternative: weight-based 30–50 mg single bolus."},"alternative":{"drug":"UFH (low-dose)","dose":"≤500 units/hr infusion (no bolus)","route":"IV","frequency":"Continuous","duration":"Until reperfusion achieved","notes":"Give alteplase BEFORE heparin to reduce bleeding risk"},"monitoring":"Hemodynamics; fibrinogen if reduced-dose protocol; bleeding signs"},"calculatorLinks":[{"id":"alteplase-pe-dosing","label":"Alteplase Dosing"}],"summary":"UFH (no bolus) + alteplase 100 mg over 2h (or 50 mg reduced-dose); cardiac arrest = 50 mg bolus + CPR","safetyLevel":"critical"}'::jsonb
