UPDATE decision_nodes SET data = '{"type":"question","module":6,"title":"Anticoagulation Selection","body":"Choice depends on renal function, bleeding risk, patient preference, and cost.\n\n**2026 AHA/ACC update:** LMWH is recommended **over UFH** for initial parenteral anticoagulation in most patients with acute PE (Class I). Reserve UFH for patients with anticipated thrombolysis, severe renal impairment, or hemodynamic instability where rapid escalation may be needed.\n\n**Key decision points:**\n• CrCl <30 mL/min → UFH preferred\n• Anticipated reperfusion (Cat D-E or unstable Cat C) → UFH\n• Cancer-associated VTE → DOAC (apixaban/rivaroxaban) or LMWH\n• Pregnancy → LMWH only (DOACs contraindicated)\n• HIT → argatroban or fondaparinux","citation":[4],"options":[{"label":"DOAC (Preferred)","description":"Apixaban, rivaroxaban, edoxaban, dabigatran","next":"pe-doac"},{"label":"LMWH → Warfarin","description":"Enoxaparin bridge to warfarin (INR target 2–3)","next":"pe-lmwh-warfarin"},{"label":"Renal/Hepatic Impairment","description":"CrCl <30 or severe hepatic disease","next":"pe-renal-hepatic"}],"summary":"DOACs preferred; CrCl <30 use UFH; cancer VTE use DOAC or LMWH; pregnancy use LMWH only; HIT use argatroban/fondaparinux"}'::jsonb
WHERE id = 'pe-anticoag-selection' AND tree_id = 'pe-treatment';

